import { AuthError, ErrorCodeMessage } from "../errors.js";
/**
 * Class representing the configuration of the application.
 */
export class Config {
    /**
     * Base class Config, which type is the Identity Provider.
     * It can be either 'base','ldap' or 'idcs'
     * @param {string} authType
     */
    constructor(authType) {
        this.authType = authType;
    }
}
/**
 * Class representing the configuration of the onprem application.
 */
/**
 * @internal
 */
export class ONPREMConfig extends Config {
    /**
     * Constructs the onprem config.
     * @param {string} domainURL
     * @param {string} appID
     * @param {string} authID
     * @param {string} authType
     * @param {string} projectID
     */
    constructor(domainURL, appID, authID, authType, projectID) {
        super(authType);
        this.authID = authID;
        this.appID = appID;
        this.domainURL = domainURL;
        this.projectID = projectID;
    }
}
ONPREMConfig.AUTHENTICATE_REST_EP = "authenticate";
ONPREMConfig.SELF_REGISTER_EP = "useradd";
ONPREMConfig.UPDATE_PASSWORD_HELPER = "changePassword";
ONPREMConfig.UPDATE_PROFILE_HELPER = "profile";
ONPREMConfig.REVOKE_REFRESH_TOKEN = "rf/revoke";
ONPREMConfig.SEND_EMAIL_VERIFICATION = "sendemail";
ONPREMConfig.SEND_PASSWORD_RESET_EMAIL = "sendemail";
ONPREMConfig.CONFIRM_PASSWORD_RESET = "resetpwd";
ONPREMConfig.VERIFY_PASSWORD_RESET_CODE = "verifycode";
ONPREMConfig.SIGN_IN_WITH_CREDENTIAL = 'getcredential';
ONPREMConfig.REDIRECT_RESULT_EP = 'redirectResult';
/**
 * Class representing the configuration of the IDCS application.
 */
/**
 * @internal
 */
export class IDCSConfig extends ONPREMConfig {
    /**
     * Constructs the IDCS config.
     * @param {string} domainURL
     * @param {string} appID
     * @param {string} authID
     * @param {string} authType
     * @param {string} projectID
     * @param {string} idcsDomainURL
     */
    constructor(domainURL, appID, authID, authType, projectID, idcsDomainURL) {
        super(domainURL, appID, authID, authType, projectID);
        this.idcsDomainURL = idcsDomainURL.replace(/\/+$/, "");
    }
}
IDCSConfig.LOGOUT_REST_EP = "/oauth2/v1/userlogout";
/**
* Internal method to get the config of the auth.
*/
/**
 * @internal
 */
export function getConfig(app) {
    let projectConfig = app.options;
    if (projectConfig.authType === 'base' ||
        projectConfig.authType === 'ldap') {
        return new ONPREMConfig(`${projectConfig.ordsHost}_/baas-services/idm/onprem/${projectConfig.projectID}/`, projectConfig.appID ?? "", projectConfig.authID ?? "", projectConfig.authType, projectConfig.projectID ?? "");
    }
    else if (projectConfig.authType === 'idcs') {
        return new IDCSConfig(`${projectConfig.ordsHost}_/baas-services/idm/idcs/${projectConfig.projectID}/`, projectConfig.appID ?? "", projectConfig.authID ?? "", projectConfig.authType, projectConfig.projectID ?? "", projectConfig.idcsDomainURL ?? "");
    }
    // else if (projectConfig.authType === 'base_s'
    //   || projectConfig.authType === 'ldap_s') {
    //   return new ONPREMSRPConfig(
    //     `${projectConfig.ordsHost}_/baas-services/idm/onprem/${projectConfig.projectID}/`,
    //     projectConfig.appID ?? "",
    //     projectConfig.authID ?? "",
    //     projectConfig.authType,
    //     projectConfig.projectID ?? ""
    //   )
    // } 
    else {
        throw new AuthError(ErrorCodeMessage.SERVER_ERROR, `Unsupported authType: ${projectConfig.authType}`);
    }
}
